def _row(t, v):
    s, buyer, fit, lic, data, ch, price, cost, ppl, gng, reg = v
    plan = " Planning only: partner with a licensed firm." if reg else ""
    if price >= 100:
        P = int(price); C = int(cost)
        m = P - C
        pct = round(100 * m / P) if P else 0
        money = "Price " + s + " at HK$" + format(P, ",") + " with cost HK$" + format(C, ",") + " to leave HK$" + format(m, ",") + " (" + str(pct) + " percent)." if P else "Price after a licensed partner sets terms."
    else:
        P = price; C = cost
        m = round(P - C, 2)
        pct = round(100 * m / P) if P else 0
        money = "Price at HK$" + str(P) + " with cost HK$" + str(C) + " to leave HK$" + str(m) + " (" + str(pct) + " percent)." if P else "Price after a licensed partner sets terms."
    return [
        ("Read the Hong Kong market for " + s + ": size the buyers, " + buyer + ", in one district first. " + fit + ".",
         "Count 50 likely buyers in one district and ask 10 what they pay today."),
        ("Test fit: does " + s + " solve a real local pain? " + fit + "." + plan,
         "Run a two-week pilot in one estate or street and note repeat use."),
        ("Register and license: check business registration, the right business type and sector rules. " + lic + ". Check current rule.",
         "Make a one-page list of each licence, who grants it and how long it takes."),
        ("Data and trust: Hong Kong's personal data law asks you to say why you collect data, keep it safe and delete it. Watch " + data + ".",
         "Write a short notice in Chinese and English and keep only fields you use."),
        ("Find customers through " + ch + ". Write in Traditional Chinese and English; use Cantonese for chat.",
         "Post one bilingual offer and track which channel gives the most replies."),
        ("Price and money in HKD. Hong Kong has no sales tax, but profits tax applies; check current rate and a tax adviser. " + money,
         "Build a table of price, unit cost, rent and staff to find monthly break-even."),
        ("People and partners: hire " + ppl + ". Check employment contract, holiday and the Mandatory Provident Fund (about 5 percent each from employer and worker, with caps; check current rule).",
         "List three roles, pay in HKD and the MPF share for each."),
        ("Launch plan with go/no-go: " + gng + ". Check current rules before you scale.",
         "Set a four-week launch with a stop rule: no signed pilot, no spend."),
    ]

R_hk_3 = {k: [tuple(r) for r in _row(k, v)] for k, v in _T.items()}
